const TEAMS=[{"id":1,"name":"Team 1"},{"id":2,"name":"Team 2"},{"id":3,"name":"Team 3"}];
const HTML="<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>FastForge · Fan Favorite</title><meta name=\"description\" content=\"Which team won you over? Pick your FastForge fan favorite.\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\">\n<style>\n:root{font-family:Arial,Helvetica,sans-serif;color:#1b2b33;background:#fbfbf4;font-synthesis:none;--ink:#1b2b33;--yellow:#f9cf2e;--cyan:#26c0e2;--pink:#f4a6c9}*{box-sizing:border-box}body{margin:0;border-top:8px solid var(--yellow)}button,a{-webkit-tap-highlight-color:transparent}button{font:inherit;color:inherit;cursor:pointer}button:disabled{cursor:wait;opacity:.55}button:focus-visible,a:focus-visible{outline:3px solid #087b91;outline-offset:5px}main{max-width:1020px;margin:auto;padding:32px 34px 24px}header{display:flex;justify-content:space-between;align-items:center;gap:20px;border-bottom:2px solid var(--ink);padding-bottom:24px}.brand{color:var(--ink);font-size:27px;font-weight:950;letter-spacing:-1.5px;text-decoration:none;display:flex;align-items:center}.brand span{color:#087b91}.brand i{color:var(--ink);font-style:normal;font-size:36px;line-height:1;margin-left:10px}.event-tag{font-size:12px;letter-spacing:1.3px;font-weight:800}.intro{padding:38px 0 30px}.eyebrow{font-size:13px;font-weight:800;letter-spacing:1.5px;display:flex;align-items:center;gap:8px}.tiny-star{font-size:23px;color:#087b91}h1{font-size:clamp(40px,6vw,68px);line-height:1.02;font-weight:950;letter-spacing:-3px;margin:14px 0 16px}h1 span{display:inline-block;background:var(--yellow);padding:3px 11px 6px;transform:rotate(-1deg)}.intro>p{font-size:19px;line-height:1.5;margin:0;color:#52636a}.vote-panel{border:2px solid var(--ink);background:#fff;box-shadow:7px 7px 0 var(--ink)}.panel-top{padding:25px 28px 23px;border-bottom:2px solid var(--ink);background:#e8f8fc}h2{margin:0;font-size:26px;line-height:1.2;font-weight:900;letter-spacing:-.7px}.panel-top p{font-size:16px;line-height:1.5;color:#52636a;margin:10px 0 0}.team-options{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:13px;padding:28px}.team-option{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:7px;border:2px solid var(--ink);background:#fff;min-height:168px;box-shadow:3px 3px 0 var(--ink);transition:transform .12s,background .12s}.team-option:hover:enabled{background:var(--yellow);transform:translate(-1px,-2px)}.team-option:nth-child(even):hover:enabled{background:var(--cyan)}.team-option.selected{background:var(--yellow)}.team-label{font-size:14px;letter-spacing:1.6px;font-weight:800}.team-option strong{font-size:56px;line-height:1;font-weight:950;letter-spacing:-2px}.vote-label{font-size:12px;font-weight:800;letter-spacing:.8px;margin-top:7px}.panel-foot{display:flex;align-items:center;justify-content:space-between;gap:18px;border-top:1px solid #dce2e1;padding:18px 28px;font-size:13px;line-height:1.5;color:#52636a}.voted-banner{display:flex;gap:14px;align-items:center;padding:20px 26px;background:#fff5c8;border-bottom:2px solid var(--ink)}.check{display:grid;place-items:center;width:34px;height:34px;flex-shrink:0;border:2px solid var(--ink);background:var(--yellow);font-size:20px;font-weight:900}.voted-banner p{font-size:13px;line-height:1.5;font-weight:700;margin:0;flex:1}.voted-banner p strong{font-size:17px}.voted-banner p span{display:block;font-size:14px;font-weight:400;color:#52636a;margin-top:3px}.small-button{border:2px solid var(--ink);padding:10px 13px;background:var(--yellow);font-size:13px;font-weight:800;white-space:nowrap}footer{display:flex;justify-content:space-between;gap:16px;padding-top:30px;font-size:10px;letter-spacing:1px;line-height:1.5;color:#52636a}footer strong{color:var(--ink)}.error{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:15px 18px;border:2px solid var(--ink);background:#fce7f1;margin-bottom:20px;font-size:15px}.error button{border:0;background:transparent;text-decoration:underline;font-weight:800;white-space:nowrap}@media(max-width:650px){main{padding:24px 18px}.event-tag{font-size:9px;max-width:110px;text-align:right;line-height:1.5}.brand{font-size:24px}.intro{padding:30px 0 24px}h1{font-size:42px;letter-spacing:-2px}.intro>p{font-size:17px}.panel-top{padding:23px 20px}h2{font-size:23px}.team-options{padding:20px;gap:11px;grid-template-columns:repeat(3,minmax(0,1fr))}.team-option{min-height:125px}.team-option strong{font-size:43px}.vote-label{font-size:10px}.team-label{font-size:12px}.panel-foot{padding:17px 20px;align-items:flex-start;flex-direction:column;gap:8px}.voted-banner{padding:17px 20px;flex-wrap:wrap}footer{font-size:8px}.vote-panel{box-shadow:5px 5px 0 var(--ink)}}@media(prefers-reduced-motion:reduce){*{transition:none!important}}\n.team-label{max-width:100%;overflow-wrap:anywhere;text-align:center;padding:0 8px}.voted-banner p strong{text-transform:uppercase}\ndialog{width:min(480px,calc(100vw - 32px));max-height:calc(100dvh - 32px);overflow:auto;padding:0;color:var(--ink);border:2px solid var(--ink);background:#fff;box-shadow:7px 7px 0 var(--ink)}dialog::backdrop{background:#1b2b33b3}dialog [hidden]{display:none!important}.settings-head{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:18px 24px;background:#e8f8fc;border-bottom:2px solid var(--ink)}.settings-head h2{font-size:23px}.settings-close{width:44px;height:44px;margin:-6px -10px -6px 0;border:0;background:transparent;font-size:24px;line-height:1}.settings-section{margin:0;padding:20px 24px;border:0;border-bottom:1px solid #dce2e1}.settings-section:last-child{border-bottom:0}.settings-section h3{margin:0 0 12px;font-size:16px;font-weight:900}.settings-field{display:block;margin-bottom:12px;font-size:13px;font-weight:800}.settings-field input{display:block;width:100%;min-height:44px;margin-top:6px;padding:9px 11px;font:400 16px Arial,Helvetica,sans-serif;color:var(--ink);background:#fff;border:2px solid var(--ink);border-radius:0}.settings-field input:focus-visible,dialog button:focus-visible{outline:3px solid #087b91;outline-offset:2px}.settings-note{margin:0 0 14px;font-size:14px;line-height:1.5;color:#52636a}.settings-actions{display:flex;flex-wrap:wrap;align-items:center;gap:10px}.settings-actions button{min-height:44px}.settings-danger{border:2px solid var(--ink);padding:10px 13px;background:#fce7f1;font-size:13px;font-weight:800}.settings-danger.confirm{color:#fff;background:#a3123f}.settings-plain{border:0;padding:10px 13px;background:transparent;font-size:13px;font-weight:800;text-decoration:underline;text-underline-offset:4px}.settings-status{min-height:21px;margin:12px 0 0;font-size:14px;line-height:1.5;font-weight:700;color:#087b91}.settings-status.bad{color:#a3123f}\n.settings-total{margin:14px 0 6px;font-size:15px;font-weight:800}.settings-standings{margin:0;padding:0;list-style:none}.settings-standings li{display:grid;grid-template-columns:28px minmax(0,1fr) auto;gap:10px;align-items:baseline;padding:9px 0;border-bottom:1px solid #dce2e1;font-size:15px;overflow-wrap:anywhere}.settings-standings li:last-child{border-bottom:0}.settings-standings li>span:first-child{font-weight:800}.settings-standings strong{white-space:nowrap}\n</style>\n</head>\n<body>\n<main>\n  <header><a class=\"brand\" href=\"/fan-favorite\" aria-label=\"FastForge fan favorite\">FAST<span>FORGE</span><i aria-hidden=\"true\">✳</i></a><span class=\"event-tag\">THE AUDIENCE GETS A SAY</span></header>\n  <section class=\"intro\"><div class=\"eyebrow\"><span class=\"tiny-star\" aria-hidden=\"true\">✦</span> THE PEOPLE’S PICK</div><h1>FAN <span>FAVORITE.</span></h1><p>Three teams. One crowd favorite. You decide.</p></section>\n  <div id=\"poll\"></div>\n  <footer><span>BIG IDEAS. REAL BUILDS. <strong>YOUR FAVORITE.</strong></span><span>FASTFORGE FAN VOTE</span></footer>\n</main>\n<dialog id=\"settings\" aria-labelledby=\"settings-title\">\n  <div class=\"settings-head\"><h2 id=\"settings-title\">Poll settings</h2><button type=\"button\" class=\"settings-close\" id=\"settings-close\" aria-label=\"Close settings\">×</button></div>\n  <div class=\"settings-section\">\n    <label class=\"settings-field\">Organizer passcode<input id=\"settings-passcode\" type=\"password\" autocomplete=\"off\"></label>\n    <p class=\"settings-note\">Needed to see results, save names or reset votes.</p>\n    <p class=\"settings-status\" id=\"settings-status\" role=\"status\"></p>\n  </div>\n  <div class=\"settings-section\">\n    <h3>Results</h3>\n    <p class=\"settings-note\">Only organizers can see these. The audience never does.</p>\n    <div class=\"settings-actions\"><button type=\"button\" class=\"small-button\" id=\"settings-results\">Show results</button></div>\n    <p class=\"settings-total\" id=\"settings-total\" hidden></p>\n    <ol class=\"settings-standings\" id=\"settings-standings\" hidden></ol>\n  </div>\n  <form class=\"settings-section\" id=\"settings-names\">\n    <h3>Team names</h3>\n    <div id=\"settings-name-fields\"></div>\n    <div class=\"settings-actions\"><button type=\"submit\" class=\"small-button\" id=\"settings-save\">Save names</button></div>\n  </form>\n  <div class=\"settings-section\">\n    <h3>Reset votes</h3>\n    <p class=\"settings-note\" id=\"settings-reset-note\"></p>\n    <div class=\"settings-actions\"><button type=\"button\" class=\"settings-danger\" id=\"settings-reset\">Reset all votes</button><button type=\"button\" class=\"settings-plain\" id=\"settings-reset-cancel\" hidden>Cancel</button></div>\n  </div>\n</dialog>\n<script>\n// Team names come from teams.json; scripts/build.mjs fills them in.\nconst TEAMS=[{\"id\":1,\"name\":\"Team 1\"},{\"id\":2,\"name\":\"Team 2\"},{\"id\":3,\"name\":\"Team 3\"}];\nconst app=document.getElementById('poll');\nlet poll={teams:TEAMS.map(({id,name})=>({team:id,name})),myVote:null};\nlet ready=false,saving=null,error='',updating=false;\nlet busy=false,token=null,revision=0,voteFailed=false;\n\nfunction esc(value){return String(value).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'})[c])}\nfunction teamName(id){return poll.teams.find(team=>team.team===id)?.name??'Team'}\nfunction votingHeaders(){\n  if(!token){try{token=localStorage.getItem('fastforge-fan-voter')}catch{}}\n  if(!token||!/^[a-f0-9-]{36}$/.test(token)){token=crypto.randomUUID();try{localStorage.setItem('fastforge-fan-voter',token)}catch{}}\n  return {'X-Fan-Voter':token};\n}\nfunction rememberVoter(data){if(data.voterToken){token=data.voterToken;try{localStorage.setItem('fastforge-fan-voter',data.voterToken)}catch{}}}\nasync function api(path,options,fallback){\n  let response,data;\n  try{response=await fetch(path,{cache:'no-store',credentials:'same-origin',...options});data=await response.json()}catch{throw new Error(fallback)}\n  if(!response.ok)throw new Error(data.error||fallback);\n  return data;\n}\n\nasync function refresh(){\n  if(busy)return;busy=true;updating=true;render();const version=revision;\n  try{const data=await api('/api/poll',{headers:votingHeaders()},'Could not reach the poll. Please try again.');rememberVoter(data);if(version===revision)poll=data;ready=true;if(!voteFailed)error='';}\n  catch(e){if(!voteFailed)error=e.message;}\n  finally{busy=false;updating=false;render();}\n}\nasync function vote(team){\n  if(!ready||saving!==null)return;revision++;saving=team;error='';voteFailed=false;render();\n  try{const data=await api('/api/vote',{method:'POST',headers:{'Content-Type':'application/json',...votingHeaders()},body:JSON.stringify({team,voterToken:token})},'Could not save your vote. Please try again.');rememberVoter(data);poll=data;}\n  catch(e){error=e.message;voteFailed=true;}\n  finally{saving=null;render();}\n}\n\nfunction votePanel(){\n  const locked=!ready||saving!==null?' disabled':'';\n  const banner=poll.myVote?`<div class=\"voted-banner\" role=\"status\"><div class=\"check\" aria-hidden=\"true\">✓</div><p>YOU PICKED <strong>${esc(teamName(poll.myVote))}.</strong><span>Your vote is in. Thanks for cheering them on!</span></p></div>`:'';\n  return `<section class=\"vote-panel\" aria-labelledby=\"vote-title\">${banner}<div class=\"panel-top\"><h2 id=\"vote-title\">Which team did you like the most?</h2><p>Tap your favorite to cast your vote.</p></div><div class=\"team-options\">${TEAMS.map(({id:team})=>{const name=teamName(team);return `<button type=\"button\" class=\"team-option${poll.myVote===team?' selected':''}\" data-vote=\"${team}\"${locked} aria-label=\"Vote for ${esc(name)}\" aria-pressed=\"${poll.myVote===team}\"><span class=\"team-label\">${name===`Team ${team}`?'TEAM':esc(name)}</span><strong>${team}</strong><span class=\"vote-label\">${saving===team?'SAVING…':poll.myVote===team?'YOUR PICK ✓':'VOTE ↗'}</span></button>`}).join('')}</div><div class=\"panel-foot\"><span>${ready?'One vote per browser. You can change your pick.':'Connecting to the poll…'}</span></div></section>`;\n}\n\n// Patch the page in place so focus, live regions and bar transitions survive each refresh.\nfunction morph(node,next){\n  if(node.isEqualNode(next))return;\n  if(node.nodeType===3&&next.nodeType===3){node.nodeValue=next.nodeValue;return}\n  if(node.nodeName!==next.nodeName||node.nodeType!==1){node.replaceWith(next);return}\n  for(const {name} of [...node.attributes])if(!next.hasAttribute(name))node.removeAttribute(name);\n  for(const {name,value} of [...next.attributes])if(node.getAttribute(name)!==value)node.setAttribute(name,value);\n  const current=[...node.childNodes],incoming=[...next.childNodes];\n  incoming.forEach((child,i)=>current[i]?morph(current[i],child):node.appendChild(child));\n  current.slice(incoming.length).forEach(child=>child.remove());\n}\nfunction render(){\n  const next=document.createElement('div');next.id='poll';\n  next.innerHTML=(error?`<div class=\"error\" role=\"alert\"><span>${esc(error)}</span><button type=\"button\" data-action=\"refresh\"${updating?' disabled':''}>Try again</button></div>`:'')+votePanel();\n  morph(app,next);\n}\n\napp.addEventListener('click',event=>{\n  const button=event.target.closest('button');if(!button||button.disabled)return;\n  if(button.dataset.vote)return void vote(Number(button.dataset.vote));\n  const action=button.dataset.action;\n  if(action==='refresh'){voteFailed=false;void refresh()}\n});\n// The ballot only needs to pick up renames and resets.\nsetInterval(()=>{if(document.visibilityState==='visible')void refresh()},12000);\n\n// Organizer settings popup: Cmd+Shift+U on Mac, Ctrl+Shift+U on Windows.\nconst settings=document.getElementById('settings'),passcodeInput=document.getElementById('settings-passcode'),settingsStatus=document.getElementById('settings-status'),nameFields=document.getElementById('settings-name-fields'),namesForm=document.getElementById('settings-names'),saveButton=document.getElementById('settings-save'),resetButton=document.getElementById('settings-reset'),resetCancel=document.getElementById('settings-reset-cancel'),resetNote=document.getElementById('settings-reset-note'),resultsButton=document.getElementById('settings-results'),standings=document.getElementById('settings-standings'),standingsTotal=document.getElementById('settings-total');\nlet confirmingReset=false,adminBusy=false;\nnameFields.innerHTML=TEAMS.map(({id,name})=>`<label class=\"settings-field\">Team ${id}<input type=\"text\" data-team=\"${id}\" maxlength=\"40\" placeholder=\"${esc(name)}\" autocomplete=\"off\"></label>`).join('');\nconst nameInputs=[...nameFields.querySelectorAll('input')];\nfunction defaultName(id){return TEAMS.find(team=>team.id===id)?.name}\nfunction fillNames(){for(const input of nameInputs){const id=Number(input.dataset.team),name=teamName(id);input.value=name===defaultName(id)?'':name}}\nfunction setStatus(message,bad=false){settingsStatus.textContent=message;settingsStatus.classList.toggle('bad',bad)}\nfunction showReset(){\n  resetNote.textContent=confirmingReset?'This permanently deletes every vote and can’t be undone.':'Clears every vote so the crowd can vote again. Team names stay.';\n  resetButton.textContent=confirmingReset?'Yes, delete all votes':'Reset all votes';\n  resetButton.classList.toggle('confirm',confirmingReset);resetCancel.hidden=!confirmingReset;\n}\nfunction setAdminBusy(value){adminBusy=value;for(const button of [saveButton,resetButton,resetCancel,resultsButton])button.disabled=value}\nfunction hideStandings(){standings.replaceChildren();standings.hidden=true;standingsTotal.hidden=true}\nfunction showStandings(data){\n  standingsTotal.textContent=`${data.total.toLocaleString()} ${data.total===1?'vote':'votes'} cast`;standingsTotal.hidden=false;\n  standings.replaceChildren(...data.teams.map(team=>{\n    const row=document.createElement('li'),rank=document.createElement('span'),name=document.createElement('span'),count=document.createElement('strong');\n    rank.textContent=team.rank??'—';name.textContent=team.name;count.textContent=`${team.votes.toLocaleString()} ${team.votes===1?'vote':'votes'} · ${team.percentage}%`;\n    row.append(rank,name,count);return row;\n  }));standings.hidden=false;\n}\nasync function openSettings(){\n  confirmingReset=false;setStatus('');hideStandings();fillNames();showReset();settings.showModal();passcodeInput.focus();\n}\n// Returns the latest results, with vote counts, once the server has accepted the request.\nasync function adminRequest(body,fallback){\n  if(adminBusy)return null;\n  if(!passcodeInput.value){setStatus('Enter the organizer passcode first.',true);passcodeInput.focus();return null}\n  if(!ready){setStatus('Still connecting to the poll. Please try again in a moment.',true);return null}\n  setAdminBusy(true);setStatus(body.action==='results'?'Loading…':'Saving…');revision++;\n  try{\n    const data=await api('/api/fan-admin',{method:'POST',headers:{'Content-Type':'application/json',...votingHeaders()},body:JSON.stringify({...body,passcode:passcodeInput.value})},fallback);\n    rememberVoter(data);poll=data;render();return data;\n  }catch(e){setStatus(e.message,true);if(e.message==='Incorrect passcode.'){passcodeInput.select();passcodeInput.focus()}return null}\n  finally{setAdminBusy(false)}\n}\nresultsButton.addEventListener('click',async()=>{\n  const data=await adminRequest({action:'results'},'Could not load the results. Please try again.');\n  if(data){setStatus('');showStandings(data);resultsButton.textContent='Refresh results'}\n});\nnamesForm.addEventListener('submit',async event=>{\n  event.preventDefault();\n  const names=Object.fromEntries(nameInputs.map(input=>[input.dataset.team,input.value]));\n  if(await adminRequest({action:'rename',names},'Could not save the names. Please try again.')){fillNames();showReset();setStatus('Team names saved.')}\n});\nresetButton.addEventListener('click',async()=>{\n  if(!confirmingReset){\n    if(!passcodeInput.value){setStatus('Enter the organizer passcode first.',true);passcodeInput.focus();return}\n    confirmingReset=true;setStatus('');showReset();return;\n  }\n  const done=await adminRequest({action:'reset'},'Could not reset the votes. Please try again.');\n  if(done){confirmingReset=false;setStatus('All votes have been reset.');hideStandings();showReset()}\n});\nresetCancel.addEventListener('click',()=>{confirmingReset=false;setStatus('');showReset();resetButton.focus()});\ndocument.getElementById('settings-close').addEventListener('click',()=>settings.close());\nsettings.addEventListener('close',()=>{passcodeInput.value='';confirmingReset=false;hideStandings();resultsButton.textContent='Show results'});\nwindow.addEventListener('keydown',event=>{\n  if(!(event.metaKey||event.ctrlKey)||!event.shiftKey||event.altKey||event.key.toLowerCase()!=='u')return;\n  event.preventDefault();if(event.repeat)return;\n  if(settings.open)settings.close();else void openSettings();\n},true);\n\nrender();void refresh();\n</script>\n</body>\n</html>\n";
// Fan Favorite poll: the page at "/", the ballot at /api/poll, voting at /api/vote and organizer settings and results at /api/fan-admin.
// Vote counts stay private: only /api/fan-admin, behind the passcode, returns them.
// TEAMS and HTML are prepended by scripts/build.mjs.
const COOKIE='ff_fan',MAX_NAME=40;
function json(data,status=200,extra={}){return new Response(JSON.stringify(data),{status,headers:{'Content-Type':'application/json','Cache-Control':'no-store',...extra}})}
function validToken(value){return typeof value==='string'&&/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/.test(value)}
function voterId(request){
  const cookie=request.headers.get('cookie')?.match(/(?:^|;\s*)ff_fan=([a-f0-9-]{36})(?:;|$)/)?.[1];
  if(validToken(cookie))return cookie;
  const header=request.headers.get('X-Fan-Voter');return validToken(header)?header:null;
}
async function results(db,id){
  const counts=await db.prepare('SELECT team, COUNT(*) AS votes FROM fan_votes GROUP BY team').all();
  const own=await db.prepare('SELECT team FROM fan_votes WHERE voter_id = ?').bind(id).first();
  const names=await db.prepare('SELECT team, name FROM fan_team_names').all();
  const teams=TEAMS.map(({id,name})=>({team:id,name:names.results.find(x=>x.team===id)?.name||name,votes:Number(counts.results.find(x=>x.team===id)?.votes||0)})).sort((a,b)=>b.votes-a.votes||a.team-b.team);
  const total=teams.reduce((sum,x)=>sum+x.votes,0);
  return {voterToken:id,teams:teams.map(x=>({...x,rank:x.votes?teams.findIndex(y=>y.votes===x.votes)+1:null,percentage:total?Math.round(x.votes/total*100):0})),total,myVote:TEAMS.some(team=>team.id===own?.team)?own.team:null};
}
// What the public may see: team names in a fixed order and this voter's own pick, so responses can't reveal who is ahead.
function ballot({voterToken,teams,myVote}){return {voterToken,myVote,teams:teams.map(({team,name})=>({team,name})).sort((a,b)=>a.team-b.team)}}
async function getPoll(request,db){
  try{
    if(!db)throw new Error('Missing database');
    const existing=voterId(request),id=existing||crypto.randomUUID();
    const data=ballot(await results(db,id));
    return json(data,200,existing?{}:{'Set-Cookie':`${COOKIE}=${id}; HttpOnly; SameSite=Lax; Path=/; Max-Age=31536000${new URL(request.url).protocol==='https:'?'; Secure':''}`});
  }catch{return json({error:'Voting is temporarily unavailable. Please try again.'},503)}
}
async function castVote(request,db){
  if(request.headers.get('origin')!==new URL(request.url).origin)return json({error:'Please vote from this page.'},403);
  try{
    const text=await request.text();if(text.length>4096)return json({error:'Invalid vote.'},413);
    let body;try{body=JSON.parse(text)}catch{return json({error:'Please choose a team.'},400)}
    const id=voterId(request)||(validToken(body?.voterToken)?body.voterToken:null);if(!id)return json({error:'Reconnect before voting. Please try again.'},401);
    const team=body?.team;if(!Number.isInteger(team)||!TEAMS.some(option=>option.id===team))return json({error:`Please choose one of the ${TEAMS.length} teams.`},400);
    if(!db)throw new Error('Missing database');
    await db.prepare('INSERT INTO fan_votes (voter_id, team, updated_at) VALUES (?, ?, ?) ON CONFLICT(voter_id) DO UPDATE SET team = excluded.team, updated_at = excluded.updated_at').bind(id,team,new Date().toISOString()).run();
    return json(ballot(await results(db,id)));
  }catch{return json({error:'Your vote could not be saved. Please try again.'},503)}
}
async function samePasscode(a,b){
  const hash=async value=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value)))].join();
  return await hash(a)===await hash(b);
}
// Organizer settings. Every change needs the FAN_ADMIN_PASSCODE secret, because the page itself is public.
async function adminAction(request,env){
  if(request.headers.get('origin')!==new URL(request.url).origin)return json({error:'Please use this page to change settings.'},403);
  if(!env.FAN_ADMIN_PASSCODE)return json({error:'The settings passcode has not been set up yet.'},503);
  try{
    const text=await request.text();if(text.length>4096)return json({error:'That request is too large.'},413);
    let body;try{body=JSON.parse(text)}catch{return json({error:'Invalid request.'},400)}
    if(typeof body?.passcode!=='string'||!await samePasscode(body.passcode,env.FAN_ADMIN_PASSCODE))return json({error:'Incorrect passcode.'},401);
    const db=env.DB;if(!db)throw new Error('Missing database');
    if(body.action==='rename'){
      const statements=[];
      for(const {id} of TEAMS){
        const raw=body.names?.[id];if(typeof raw!=='string')return json({error:'Please name every team.'},400);
        const name=raw.replace(/[\u0000-\u001f\u007f]/g,' ').replace(/\s+/g,' ').trim();
        if(name.length>MAX_NAME)return json({error:`Team names can be up to ${MAX_NAME} characters.`},400);
        statements.push(name?db.prepare('INSERT INTO fan_team_names (team, name, updated_at) VALUES (?, ?, ?) ON CONFLICT(team) DO UPDATE SET name = excluded.name, updated_at = excluded.updated_at').bind(id,name,new Date().toISOString()):db.prepare('DELETE FROM fan_team_names WHERE team = ?').bind(id));
      }
      await db.batch(statements);
    }else if(body.action==='reset')await db.prepare('DELETE FROM fan_votes').run();
    else if(body.action!=='results')return json({error:'Unknown setting.'},400);
    return json(await results(db,voterId(request)||crypto.randomUUID()));
  }catch{return json({error:'That change could not be saved. Please try again.'},503)}
}
export default {async fetch(request,env){
  const path=new URL(request.url).pathname;
  if(path==='/'&&request.method==='GET')return new Response(HTML,{headers:{'Content-Type':'text/html;charset=utf-8','Cache-Control':'no-cache'}});
  if(path==='/api/poll'&&request.method==='GET')return getPoll(request,env.DB);
  if(path==='/api/vote'&&request.method==='POST')return castVote(request,env.DB);
  if(path==='/api/fan-admin'&&request.method==='POST')return adminAction(request,env);
  return json({error:'Not found.'},404);
}};
